import{_ as e,o,c as t,a7 as i}from"./chunks/framework.Bn19FVGY.js";const r="/ruidu-docs/images/orbitcontrol/user-guide/video-wall-page-grid.gif",l="/ruidu-docs/images/orbitcontrol/user-guide/video-wall-dialog-select-device.gif",m=JSON.parse('{"title":"视频墙","description":"","frontmatter":{},"headers":[],"relativePath":"orbitcontrol/user-guide/video-wall.md","filePath":"orbitcontrol/user-guide/video-wall.md"}'),s={name:"orbitcontrol/user-guide/video-wall.md"};function d(n,a,c,u,p,_){return o(),t("div",null,[...a[0]||(a[0]=[i('<h1 id="视频墙" tabindex="-1">视频墙 <a class="header-anchor" href="#视频墙" aria-label="Permalink to &quot;视频墙&quot;">​</a></h1><p>「视频墙」用于同时监控多路设备画面：将多个设备的实时视频排布在一个页面中，适合值守场景。</p><p><img src="'+r+'" alt=""></p><h2 id="布局" tabindex="-1">布局 <a class="header-anchor" href="#布局" aria-label="Permalink to &quot;布局&quot;">​</a></h2><p>页面顶部提供两种布局：</p><ul><li><strong>2×2</strong>：四分屏，4 路画面</li><li><strong>3×3</strong>：九分屏，9 路画面</li></ul><h2 id="添加设备" tabindex="-1">添加设备 <a class="header-anchor" href="#添加设备" aria-label="Permalink to &quot;添加设备&quot;">​</a></h2><p>每个画面格子初始为「添加设备」按钮，点击后弹出设备选择对话框，选择当前站点下的设备，画面自动开始推流。</p><p><img src="'+l+'" alt=""></p><h2 id="画面信息与操作" tabindex="-1">画面信息与操作 <a class="header-anchor" href="#画面信息与操作" aria-label="Permalink to &quot;画面信息与操作&quot;">​</a></h2><ul><li>每路画面左下角显示状态徽标：<strong>经纬度、电池电量、当前录像、云台变焦</strong></li><li>鼠标悬停画面，右上角出现「移除设备」按钮，点击后断开该路画面</li><li>布局与设备排布会自动保存，下次进入视频墙时恢复</li></ul><div class="tip custom-block"><p class="custom-block-title">TIP</p><p>视频墙为纯监控模式：画面默认开流、无操控控件。需要操控设备时，请前往 <a href="./live-control.html">设备控制</a>。</p></div>',12)])])}const g=e(s,[["render",d]]);export{m as __pageData,g as default};
